def solve2(r0,r1,c0,c1,H=30,W=30):
    g=[[0]*W for _ in range(H)]
    n=r1-r0+1
    color={}
    s=n; d=0
    while s>=2:
        for col in (2,5,0):
            if s<2: break
            d+=1; color[d]=col; s-=2
        if s>=4:
            d+=1; color[d]=5; s-=2
        else:
            break
    for r in range(r0,r1+1):
        for c in range(c0,c1+1):
            dd=min(r-r0,r1-r,c-c0,c1-c)
            if dd==0: g[r][c]=5
            else: g[r][c]=color.get(dd,0)
    return g
